@push('scripts')<script>(()=>{const input=document.getElementById('csv');const drop=document.getElementById('csvDropzone');const card=document.getElementById('selectedFile');const button=document.getElementById('continueButton');const name=document.getElementById('selectedFileName');const size=document.getElementById('selectedFileSize');const update=()=>{const file=input.files[0];card.hidden=!file;drop.hidden=!!file;button.disabled=!file;if(file){name.textContent=file.name;size.textContent=(file.size/1024).toFixed(1)+' KB'}};input.addEventListener('change',update);document.getElementById('removeFile').addEventListener('click',()=>{input.value='';update()});['dragenter','dragover'].forEach(event=>drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('is-dragging')}));['dragleave','drop'].forEach(event=>drop.addEventListener(event,()=>drop.classList.remove('is-dragging')));drop.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length){input.files=e.dataTransfer.files;update()}});document.getElementById('csvUploadForm').addEventListener('submit',()=>{button.disabled=true;button.textContent='Validating file…'})})();</script>@endpush